'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)],KEY='devispilot-v1';
const day=d=>{const a=new Date();a.setDate(a.getDate()+d);return new Date(a.getTime()-a.getTimezoneOffset()*60000).toISOString().slice(0,10)},money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={sent:'Envoyé',replied:'Réponse reçue',won:'Signé',lost:'Perdu'};
function seed(){return {demo:true,settings:{company:'Atelier Confort',signature:'Votre artisan',stripe:''},quotes:[{id:crypto.randomUUID(),client:'Maison Laurent',email:'',project:'Installation pompe à chaleur',amount:6480,sent:day(-7),next:day(-1),status:'sent',notes:'Exemple fictif. Valider les disponibilités pour une visite.',history:[]},{id:crypto.randomUUID(),client:'Résidence des Oliviers',email:'',project:'Climatisation réversible · 3 unités',amount:4250,sent:day(-10),next:day(0),status:'replied',notes:'Exemple fictif. Une question sur le niveau sonore.',history:[]},{id:crypto.randomUUID(),client:'Atelier Martin',email:'',project:'Entretien annuel chaudière',amount:390,sent:day(-3),next:day(4),status:'sent',notes:'Exemple fictif.',history:[]},{id:crypto.randomUUID(),client:'Maison Vidal',email:'',project:'Remplacement chaudière',amount:5120,sent:day(-15),next:day(0),status:'won',notes:'Exemple fictif. Signature déclarée ; paiement non vérifié.',history:[]},{id:crypto.randomUUID(),client:'Cabinet des Cèdres',email:'',project:'Climatisation du cabinet',amount:2890,sent:day(-8),next:day(2),status:'sent',notes:'Exemple fictif.',history:[]},{id:crypto.randomUUID(),client:'Studio des Vignes',email:'',project:'Installation monosplit',amount:1850,sent:day(-20),next:day(0),status:'lost',notes:'Exemple fictif. Projet reporté.',history:[]}]}}
function validLink(v){try{const u=new URL(v);return u.protocol==='https:'&&u.hostname==='buy.stripe.com'&&!u.username&&!u.password}catch{return false}}
function normalize(x){if(!x||!Array.isArray(x.quotes)||!x.settings)throw Error();const q=x.quotes.filter(q=>q&&typeof q.id==='string'&&typeof q.client==='string'&&typeof q.project==='string'&&Number.isFinite(q.amount)&&q.amount>0&&Object.hasOwn(labels,q.status)&&/^\d{4}-\d{2}-\d{2}$/.test(q.next)&&/^\d{4}-\d{2}-\d{2}$/.test(q.sent));return {...x,quotes:q,settings:{company:String(x.settings.company||'Mon entreprise'),signature:String(x.settings.signature||'Votre artisan'),stripe:validLink(x.settings.stripe)?x.settings.stripe:''}}}
let state;try{const raw=localStorage.getItem(KEY);state=raw?normalize(JSON.parse(raw)):seed()}catch{state=seed()}
let current=null,timer;function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',4500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Sauvegarde locale indisponible. Exportez vos données avant de fermer.');return false}}
function active(q){return ['sent','replied'].includes(q.status)}function due(){return state.quotes.filter(q=>active(q)&&q.next<=day(0)).sort((a,b)=>a.next.localeCompare(b.next))}
function date(s){return new Date(s+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short'})}
function openApp(){ $('header').hidden=true;$('#landing').hidden=true;$('#app').hidden=false;window.scrollTo(0,0);render()}
$$('[data-open]').forEach(b=>b.onclick=openApp);$('#back').onclick=()=>{$('header').hidden=false;$('#landing').hidden=false;$('#app').hidden=true;window.scrollTo(0,0)};
function tab(id){$$('.tab').forEach(el=>el.hidden=el.id!==id);$$('aside [data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===id));$('#breadcrumb').textContent={pipeline:"Vue d'ensemble",followups:'Relances à préparer',settings:'Offre & paiement'}[id];render();window.scrollTo(0,0)}$$('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
function render(){const pending=state.quotes.filter(active),won=state.quotes.filter(q=>q.status==='won'),queue=due();$('#today').textContent=new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}).toUpperCase();$('#data-label').textContent=state.demo?'DONNÉES DE DÉMONSTRATION':'DONNÉES LOCALES · NON SYNCHRONISÉES';$('#reset').textContent=state.demo?'Réinitialiser la démo':'Charger des exemples';$('#stats').innerHTML=[['Portefeuille en attente',money(pending.reduce((n,q)=>n+q.amount,0)),pending.length+' devis ouverts',''],['À relancer maintenant',queue.length, money(queue.reduce((n,q)=>n+q.amount,0))+' de devis concernés','highlight'],['Devis signés',money(won.reduce((n,q)=>n+q.amount,0)),won.length+' signatures déclarées · non encaissées',''],['Relances enregistrées',state.quotes.reduce((n,q)=>n+(q.history?.length||0),0),'Envois déclarés manuellement','']].map(([a,b,c,d])=>`<article class="stat ${d}"><p>${a}</p><strong>${b}</strong><small>${c}</small></article>`).join('');renderRows();$('#queue').innerHTML=queue.length?queue.map(q=>`<article class="queue-card"><div><p class="eyebrow">${q.next<day(0)?'SUIVI EN RETARD':'À SUIVRE AUJOURD’HUI'}</p><h3>${esc(q.client)}</h3><p>${esc(q.project)} · ${money(q.amount)} HT</p><p>${esc(q.notes||'Aucune note')} · ${q.history?.length||0} relance(s) enregistrée(s)</p></div><button class="primary" data-compose="${esc(q.id)}">Préparer le message ↗</button></article>`).join(''):'<div class="panel empty">Aucune relance échue. Retrouvez tous vos devis dans la vue d’ensemble.</div>';const f=$('#settings-form');f.elements.company.value=state.settings.company;f.elements.signature.value=state.settings.signature;f.elements.stripe.value=state.settings.stripe;$('.workspace strong').textContent=state.settings.company;$('#buy').innerHTML=state.settings.stripe?'Accéder au paiement Stripe ↗':'Vérifier la disponibilité ↗';$('#payment-note').textContent=state.settings.stripe?'Paiement hébergé par Stripe · Vérifiez le récapitulatif':'Paiement non configuré · Aucun prélèvement'}
function renderRows(){const query=$('#search').value.toLocaleLowerCase('fr'),filter=$('#filter').value;const rows=state.quotes.filter(q=>(filter==='all'||q.status===filter)&&`${q.client} ${q.project}`.toLocaleLowerCase('fr').includes(query));$('#count').textContent=`${rows.length} devis affiché(s) · Montants hors taxes`;
$('#rows').innerHTML=rows.length?rows.map(q=>`<tr><td><strong>${esc(q.client)}</strong><small>${esc(q.project)}</small></td><td><strong>${money(q.amount)}</strong></td><td><span class="status ${q.status}">${labels[q.status]}</span></td><td class="${active(q)&&q.next<=day(0)?'due':''}">${active(q)?date(q.next):'Suivi clôturé'}<small>${active(q)?(q.next<=day(0)?'Relance à préparer':'Planifiée'):(q.status==='won'?'Signature déclarée':'Sans suite')}</small></td><td><div class="row-actions">${active(q)?`<button data-compose="${esc(q.id)}">Relancer ↗</button>`:''}<button data-edit="${esc(q.id)}" aria-label="Modifier ${esc(q.client)}">Modifier</button></div></td></tr>`).join(''):'<tr><td colspan="5" class="empty">Aucun devis. Ajoutez votre première opportunité.</td></tr>'}
$('#search').oninput=renderRows;$('#filter').onchange=renderRows;
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit]'),compose=e.target.closest('[data-compose]');if(edit)editQuote(edit.dataset.edit);if(compose)composeQuote(compose.dataset.compose);if(e.target.closest('[data-close]'))e.target.closest('dialog').close()});
function editQuote(id){const q=state.quotes.find(x=>x.id===id),f=$('#quote-form');f.reset();$('#editor-title').textContent=q?'Modifier le devis':'Ajouter un devis';for(const k of ['id','client','email','project','amount','sent','status','next','notes'])f.elements[k].value=q?.[k]??({sent:day(0),next:day(3),status:'sent'}[k]||'');$('#delete').hidden=!q;$('#editor').showModal()}
$('#add').onclick=()=>editQuote();$('#quote-form').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.amount=Number(o.amount);if(!Number.isFinite(o.amount)||o.amount<=0)return toast('Montant invalide.');const old=state.quotes.find(q=>q.id===o.id);o.id=old?.id||crypto.randomUUID();o.history=old?.history||[];if(old)state.quotes=state.quotes.map(q=>q.id===o.id?o:q);else state.quotes.unshift(o);save();$('#editor').close();render();toast('Devis enregistré sur cet appareil.')};
$('#delete').onclick=()=>{const id=$('#quote-form').elements.id.value;if(confirm('Supprimer ce devis et son historique local ?')){state.quotes=state.quotes.filter(q=>q.id!==id);save();$('#editor').close();render()}};
function composeQuote(id){current=id;$('#tone').value='gentle';makeMessage();$('#composer').showModal()}
function makeMessage(){const q=state.quotes.find(q=>q.id===current);if(!q)return;$('#compose-title').textContent=q.client;$('#subject').value=`Votre projet : ${q.project}`;const t=$('#tone').value;const middle={gentle:'Avez-vous pu regarder notre proposition ? Je reste disponible pour répondre à vos questions.',help:'Souhaitez-vous que nous prenions quelques minutes pour faire le point sur la proposition et vos besoins ? Vous pouvez me communiquer vos disponibilités.',closing:'Votre projet est-il toujours d’actualité ? Si vous préférez que nous arrêtions le suivi, dites-le-moi simplement. Je respecterai votre choix.'}[t];$('#message').value=`Bonjour,\n\nJe reviens vers vous concernant notre devis du ${date(q.sent)} pour votre projet « ${q.project} ».\n\n${middle}\n\nBien cordialement,\n${state.settings.signature}\n${state.settings.company}`}
$('#tone').onchange=makeMessage;$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#message').value);toast('Message copié.')}catch{$('#message').select();toast('Sélectionnez puis copiez le message.')}};$('#mail').onclick=()=>{const q=state.quotes.find(q=>q.id===current);if(!q?.email)return toast('Ajoutez un email au devis, ou copiez le message.');location.href=`mailto:${encodeURIComponent(q.email)}?subject=${encodeURIComponent($('#subject').value)}&body=${encodeURIComponent($('#message').value)}`};$('#done').onclick=()=>{const q=state.quotes.find(q=>q.id===current);if(!q)return;q.history=q.history||[];q.history.push({at:new Date().toISOString(),subject:$('#subject').value});q.next=day(7);save();$('#composer').close();render();toast('Relance déclarée envoyée. Prochain suivi dans 7 jours.')};
$('#settings-form').onsubmit=e=>{e.preventDefault();const s=Object.fromEntries(new FormData(e.target));s.stripe=s.stripe.trim();if(s.stripe&&!validLink(s.stripe))return toast('Utilisez un lien HTTPS Stripe : https://buy.stripe.com/…');state.settings=s;save();render();toast('Paramètres enregistrés. Aucun abonnement activé par cette action.')};$('#buy').onclick=()=>{if(state.settings.stripe&&validLink(state.settings.stripe))window.open(state.settings.stripe,'_blank','noopener,noreferrer');else{openApp();tab('settings');toast('Configurez le Payment Link de votre offre dans Stripe.')}};
$('#reset').onclick=()=>{if(!confirm('Remplacer vos données locales par les exemples ? Exportez-les avant de continuer.'))return;const settings=state.settings;state=seed();state.settings=settings;save();render()};$('#clear').onclick=()=>{if(!confirm('Effacer tous les devis et paramètres locaux de cet appareil ?'))return;state={demo:false,quotes:[],settings:{company:'Mon entreprise',signature:'Votre artisan',stripe:''}};save();render();toast('Espace local vidé. Vous pouvez ajouter vos propres devis.')};
function csvCell(x){let s=String(x??'');if(/^[=+@\-\t\r\n]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
$('#export').onclick=()=>{const keys=['client','email','project','amount','sent','status','next','notes'];const csv='\uFEFF'+[keys,...state.quotes.map(q=>keys.map(k=>q[k]))].map(r=>r.map(csvCell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='devispilot-devis.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export des devis téléchargé. Historique détaillé non inclus.')};
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0],delim=first.includes(';')?';':',';const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===delim&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Guillemets non fermés.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
$('#import').onclick=()=>$('#csv').click();$('#csv').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2000000)return toast('CSV trop volumineux : maximum 2 Mo.');try{const [header,...rows]=parseCSV(await file.text());if(!header||!rows.length)throw Error('Le CSV ne contient pas de devis.');const keys=header.map(s=>s.trim().toLowerCase());for(const k of ['client','project','amount','sent','status','next'])if(!keys.includes(k))throw Error('Colonnes requises : client, project, amount, sent, status, next. Exportez la démo pour obtenir le modèle.');if(rows.length>2000)throw Error('Maximum 2 000 lignes par import.');const incoming=rows.map((r,i)=>{const q=Object.fromEntries(keys.map((k,j)=>[k,(r[j]||'').trim()]));q.amount=Number(q.amount.replace(',','.'));if(!q.client||!q.project||q.client.length>100||q.project.length>200||!Number.isFinite(q.amount)||q.amount<=0||q.amount>10000000||!Object.hasOwn(labels,q.status)||![q.sent,q.next].every(s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(new Date(s+'T12:00:00').getTime())))throw Error('Données invalides à la ligne '+(i+2)+'. Aucun devis importé.');return {...q,email:(q.email||'').slice(0,200),notes:(q.notes||'').slice(0,2000),id:crypto.randomUUID(),history:[]}});if(!confirm(`Importer ${incoming.length} devis ? ${state.demo?'Les exemples seront remplacés.':'Les devis seront ajoutés ; un second import créera des doublons.'}`))return;state.quotes=state.demo?incoming:[...state.quotes,...incoming];state.demo=false;save();render();toast(incoming.length+' devis importés.')}catch(err){toast(err.message)}};
render();
